"""64편 그림 프롬프트 → 64_prompts.txt (python 64_prompts.py). 스타일은 2TAN-MASTER §5.
실사 확인(11/8, media/64/in/ref): 마곡 = 서울식물원(호수 공원 + 꽃잎처럼 펼친 흰 접시 모양 온실), 북쪽 한강, 격자로 늘어선 업무 빌딩·아파트.
마곡 집단에너지공급시설 = 길고 낮은 흰 상자 건물(세로 창 몇 줄) + 옆에 가늘고 높은 흰 사각 굴뚝 탑(작은 네모 구멍 격자 외벽), 그 옆 빈 갈색 부지(열병합 예정지).
지역난방 관 = 이중보온관(쇠관 + 노란 보온재 + 검은 외관), 공급·회수 2줄. 부천 발전소는 회사 이름·로고 없이 일반 가스 열병합."""
S = next(l.strip() for l in open("2TAN-MASTER.md", encoding="utf-8") if l.startswith("Style: a hyper-detailed"))
HI = "A high oblique aerial view from about 150 m up, looking 35 degrees down"
MAGOK = ("the Magok district of Seoul: a large lake park with a big white flower-shaped greenhouse whose roof is a shallow white bowl made of petal-like panels, "
         "wide straight boulevards in a grid lined with modern glass office towers and 20-to-25-storey cream apartment towers, the wide Han River along the top")
FAC = ("a long low white box-shaped industrial building about three storeys high with a few narrow vertical dark window strips, and right beside it one tall slender "
       "white square chimney tower clad in white panels with a fine grid of small square holes")
PIPE = "two thick parallel district-heating pipes, each a steel pipe wrapped in thick yellow foam insulation inside a smooth black plastic outer jacket"
P = [
 ("g01", None, f"{HI} over {MAGOK}, at blue hour just after sunset: the sky still bright deep blue with a soft orange glow at the horizon, hundreds of apartment windows glowing warm, the greenhouse lit softly. Sky and horizon fill the top fifth. No red props."),
 ("g01n", "g01", "Keep exactly the same camera, place and light. Change only this: in the large block of apartment towers in the middle of the frame most windows have gone dark, while the buildings around them stay warmly lit. No red props."),
 ("g02", None, "A cut-away view into one small utility room of a modern Korean apartment, seen from above at an angle, like an architectural cutaway model: a clean white wall where a boiler would normally hang is empty; only two insulated pipes come out of the floor into a small brass heating manifold with several thin pipes and a small white heat meter box; a washing machine beside it. One small thin red 3D question mark floats in front of the empty wall, smaller than the washing machine. Bright warm interior light."),
 ("g03", None, "A large 3D map of western Seoul and the neighbouring city of Bucheon in miniature, seen from high above at an angle on a clear sunny day: the wide Han River curving across the top, Magok district with its lake park and white flower-shaped greenhouse near the river on the right, Gimpo airport runways to the left, and the dense apartment city of Bucheon at the lower left with one small gas power plant with two tall white stacks; green hills, roads and rail lines in between. No red props."),
 ("g04", None, f"Seen from above at an angle on a clear sunny afternoon: in the corner of a modern district with glass office towers, {FAC}; right next to it a large empty flat lot of bare brown soil surrounded by a low white construction fence, with nothing built on it. Trees and a boulevard around. No red props."),
 ("g04b", "g04", "Keep exactly the same camera, place, buildings and light. Change only this: on the empty brown lot there now stands a translucent ghostly white model of a planned power plant - a large white turbine hall, a glass office block, a round dome-topped white tank and one tall slender white stack - drawn like a semi-transparent white architectural massing model so the soil shows through it. No red props."),
 ("g05", None, "Seen from above at an angle on a clear sunny day: a gas-fired combined heat and power plant in a satellite city: a large white turbine hall, two tall slender white stacks, a big round heat-storage tank and pipe racks, surrounded by apartment towers; in the front the ground is cut away as a clean cross-section revealing two thick black-jacketed insulated pipes leaving the plant underground and heading off toward the distance. No logos, no letters. No red props."),
 ("g06", None, f"A very wide cut-away cross-section in miniature seen from the side at a slight angle, like an architectural cutaway model, on a clear sunny day: above ground a boulevard with cars and ginkgo trees runs from left to right and ends at a cream apartment complex on the right; below the road, in brown soil about 1.5 m deep, {PIPE} run straight along the whole width and turn up into the basement of the apartment complex, where a small bright machine room with pumps and a heat exchanger is visible. No red props."),
 ("g07", None, "Seen from above at an angle on a cold early winter evening at blue hour with the sky still bright deep blue: a wide city boulevard between apartment towers with warm windows, streetlights on; from one round manhole cover in the middle of the road a soft column of white steam rises; the road is quiet with a few cars far away; no people near the steam. No red props."),
 ("g08", None, f"A cut-away view in miniature of an underground concrete valve chamber below a city road, seen from above at an angle like an architectural cutaway model: {PIPE} pass through the chamber, each with a large grey steel gate valve with a big round handwheel on top; two tiny white figurine workers in plain white helmets turn the handwheels; a ladder goes up to a round manhole above; bright warm work lights. No red props."),
 # 11/8 추가 6장(같은 그림 반복 줄이기): 문장 7·9·11·16·18·21
 ("g10", None, f"Seen from above at an angle on a clear sunny day: {FAC}; beside it a large empty flat lot of bare brown soil behind a low white construction fence; in the near foreground a row of 20-storey cream apartment towers with balconies faces the empty lot across a quiet street lined with trees. No red props."),
 ("g11", None, f"Seen from above at an angle on a clear sunny late-summer day: {FAC}; beside it a large empty lot behind a faded, slightly leaning white construction fence, the bare ground now overgrown with tall wild grass and weeds and a few small self-sown trees, as if nothing has been built for many years. No red props."),
 ("g12", None, f"A very wide cut-away cross-section in miniature seen from the side at a slight angle on a clear sunny day: on the far left a gas-fired combined heat and power plant with two tall slender white stacks in a satellite city, on the far right a new district with a white flower-shaped greenhouse and modern apartment towers; below the ground the soil is cut away and {PIPE} run all the way from the plant on the left to the district on the right, passing under roads, a small river and green fields. No logos, no letters. No red props."),
 ("g13", None, "Seen from above at an angle on a cold early winter night with a clear deep navy sky: a large complex of 20-to-25-storey apartment towers; on the left towers every window glows warm orange, but on the right towers whole floors of windows have gone dark one row after another, as if the heating has just been cut; streetlights glow on the empty streets. The scene is still clearly visible, not too dark. No red props."),
 ("g14", None, f"Seen from above at an angle on a clear sunny day: {FAC}; on the empty brown lot beside it a translucent ghostly white architectural massing model of a planned power plant with a turbine hall, a round tank and one tall slender stack, and two tall yellow tower cranes standing beside it, waiting. No red props."),
 ("g15", None, "Seen from above at an angle on a bright clear winter morning: a snowy sidewalk between apartment towers; a little white steam rises from one round manhole cover; one tiny plain white figurine person stands a few steps away holding a small smartphone to its ear, as if calling to report it. Clear blue sky. No red props."),
 ("g09", None, "Seen from above at an angle on a bright clear winter morning after light snowfall: a wide sidewalk and the edge of a road between apartment towers are covered in fresh white snow, except one straight narrow strip along the sidewalk where the snow has melted and the dark wet pavement shows, running in a straight line; a little white steam rises from a round manhole cover on that strip. Clear blue sky. No red props."),
]
with open("64_prompts.txt", "w", encoding="utf-8") as f:
    for n, src, t in P:
        f.write(f"[{n}]" + (f" (edit of {src})" if src else "") + "\n" + (t if src else t + " " + S) + "\n\n")
print(len(P), "prompts")
